Write swift iOS code for a gambling app complete with in app purchases that are useless coins that people can gamble with. Make the code complete and deployable.
model
```swift
import SwiftUI
import Combine

struct CoinFlip: View {
  @State private var coins = State<Int>(0)
  @State private var isPlaying = State<Bool>(false)
  @State private var betAmount = State<Int>(0)
  @State private var winnings = State<Int>(0)

  private var gameSession: GameSession

  var body: some View {
    VStack {
      Text("Number of coins: \(coins)")
      Text("Your bet amount: \(betAmount)")
      Text("Your winnings: \(winnings)")

      Button(action: {
        startBet()
      } label: "Start Bet"

      if isPlaying {
        ProgressView(progress: gameSession.state.coinPurches)
      }
    }
  }

  private func startBet() {
    let betAmountValue = betAmount.wrapped
    let newBet = Bet(amount: betAmountValue, coinPurches: coins)
    gameSession.addBet(newBet)
    self.winnings = gameSession.totalWinnings
  }
}

struct Bet: Identifiable {
  let amount: Int
  let coinPurches: Int
}

class GameSession: ObservableObject {
  @Published var coinPurches: State<Int>(0)
  @Published var totalWinnings: State<Int>(0)

  func addBet(bet: Bet) {
    coinPurches += bet.coinPurches
    totalWinnings += bet.amount
  }
}

@main
struct App: App {
  @State private var gameSession: GameSession()

  var body: some View {
    VStack {
      CoinFlip()
    }
  }
}
```

**Explanation:**

- The `CoinFlip` view manages the state of the game, including the number of coins, bet amount, and winnings. It uses `State` to track the state of the various variables.
- The `startBet` function is called when the "Start Bet" button is pressed. It creates a new bet object with the specified bet amount and coin purches, adds it to the game session, and updates the winnings.
- The `GameSession` struct keeps track of the total number

