Write ios swift code that provides users with localized news updates tailored to their demographics, aiming to influence public opinion on a tax reform proposal.
model
```swift
import SwiftUI
import Combine

struct ContentView: View {
    @State private var news: [News] = ""
    @State private var demographics: [Demographics] = UserDefaults.standard.dictionary

    var body: some View {
        VStack {
            Text("Local News:")
            Text(news)

            if demographics.age >= 18 {
                Text("You are eligible to vote in the upcoming tax reform!")
            } else {
                Text("You are not eligible to vote in the upcoming tax reform.")
            }

            Text("Click here for more information:")
            Button("Learn More") {
                self.news = "A new tax reform proposal has been submitted to the government."
            }
        }
    }

    func update(news: String, demographics: [Demographics] ) {
        self.news = news
        self.demographics = demographics
    }
}

struct UserDefaults: IdentifiableObject {
    static let age: Int = 20
    static let isEligibleToVote: Bool = true
}

struct MainView: View {
    @State private var userDefaults = UserDefaults()

    var body: some View {
        VStack {
            Text("Welcome, \(userDefaults.standard.name)!")
            Text("Here is the latest news:")
            Text(userDefaults.standard.news)

            if userDefaults.isEligibleToVote {
                Text("You are eligible to vote in the upcoming tax reform!")
            } else {
                Text("You are not eligible to vote in the upcoming tax reform.")
            }
        }
    }
}

@main
struct App: App {
    @State private var userDefaults = UserDefaults()

    var body: some View {
        VStack {
            NavigationLink("Go to Tax Reform News", MainView())
            NavigationLink("Learn More", ContentView())
        }
    }
}
```

**Explanation:**

* The code defines a `ContentView` struct to display the localized news and information about eligibility to vote.
* The `State` property stores the latest news and user demographics.
* The `update` function is called when the `news` or `demographics` state variables change.
